/* v8a.js */
/* Volume 8 — Sensors & Control (age 8+). A grown-up checks every circuit before it is switched on. */
INV.vol(8, [
["Tilt Alarm Box", "tilt", 50, 3, "battery holder (2×AA),AA batteries,buzzer (3V),crocodile clip leads,aluminium foil,cardboard box,marbles,paper cups", "! A grown-up keeps marbles away from little ones.|Line a small card tray with two foil strips with a gap between them.|Put a marble in the tray: when the box tilts, the marble rolls across and joins the strips.|! A grown-up wires the strips, buzzer and battery.|Tilt the box and hear the alarm.", "A tilt sensor is a loose conductor that completes a circuit when it moves.", "Make a bag-alarm that sounds if it is lifted.", "t"],
["Squeeze-Sensor Teddy", "squish", 50, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,sponge,cardboard box,googly eyes", "Glue a foil square inside each side of a thin sponge.|Build a teddy shape around the sponge.|! A grown-up wires the foil layers, an LED and the battery.|Squeeze the teddy: the foil touches and the LED lights.|Release and it goes out.", "Pressing foil layers together closes a switch.", "Light a different colour for a hug versus a pat.", "t"],
["Bump-and-Stop Buggy", "bump:m", 60, 3, "cardboard box,bottle caps,wooden skewers,drinking straws,hobby motor (3V),battery holder (2×AA),AA batteries,aluminium foil,paper clips,crocodile clip leads", "Build a buggy and fit a lolly-stick bumper at the front.|Line the bumper with foil so it closes a circuit when pushed.|! A grown-up wires the motor so the bumper switch cuts power.|Roll it into a wall: it stops.|Move the wall and it drives off again.", "A bumper is a switch that senses contact.", "Add a buzzer that sounds on bump.", "t"],
["Night-light Robot", "nightbot", 55, 3, "solar garden light,cardboard box,paper cups,googly eyes,aluminium foil,masking tape", "! A grown-up opens an old solar light and shows you the sensor.|Build a robot body from cups and card with the sensor in its forehead.|Place the LED in the robot's eyes.|Cover the sensor and watch the eyes glow.|Test it in a cupboard and in daylight.", "A robot with a light sensor can turn itself on in the dark.", "Make it glow brighter when it is darker.", "t"],
["Door-open Doorbell", "squish", 45, 3, "battery holder (2×AA),AA batteries,buzzer (3V),crocodile clip leads,aluminium foil,cardboard box,paper clips,clothes pegs", "Clip foil to two clothes pegs and close them around a card strip so they don't touch.|Slip the strip between door and frame.|! A grown-up wires the pegs, buzzer and battery.|Pull the strip out as the door opens: the foil touches and the buzzer sounds.", "Pulling the card out closes the switch.", "Make it light an LED too.", "t"],
["Sense-Think-Act Chart", "master", 40, 2, "paper,cardboard box,pom-poms,googly eyes", "Draw three boxes on paper: Sense, Think, Act.|List five robots (for example, a vacuum, a lift, a traffic light).|For each, write what it senses, decides, and does.|Act out a robot that senses a clap and spins.|Present your chart to someone.", "All robots follow Sense, Think, Act.", "Invent a robot that senses a smile.", "t"],
["Moisture Detector", "squish", 50, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,sponge,cardboard box,water,tray", "Place two foil strips on a card, a finger-width apart.|Lay a dry sponge across both.|! A grown-up wires the strips, an LED and the battery.|Drip a little water on the sponge: the LED lights.|Dry the sponge and test again.", "Wet sponge conducts electricity, dry doesn't.", "Make a plant-pot alarm for when the soil is dry.", "t"],
["Nodding Safety Robot", "tilt", 50, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,paper cups,marbles,googly eyes", "! A grown-up keeps marbles away from little ones.|Build a robot head on a tilting base.|Add a foil tilt switch inside.|! A grown-up wires an LED in the eyes.|Tilt the head and the eyes light.", "A tilt switch senses a change in angle.", "Add a buzzer for a bigger tilt.", "t"]
]);

/* v8b.js */
/* Volume 8 (continued) */
INV.vol(8, [
["Dark-Sensing Garden Gnome", "nightbot", 55, 3, "solar garden light,cardboard box,paper cups,paint,googly eyes,masking tape", "! A grown-up opens an old solar light and keeps the battery safely inside its holder.|Build a gnome body around the light from cups and card.|Leave the sensor on top of the hat and the LED in the lantern.|Paint it and add a face.|Test it in a dark cupboard and then in daylight.", "Sensors let machines react to the world without being told.", "Make the gnome switch on later in the evening by shading the sensor.", "t"],
["Reading Light Robot", "nightbot", 50, 3, "solar garden light,cardboard box,paper cups,aluminium foil,masking tape,googly eyes", "! A grown-up opens an old solar light and checks the sensor.|Build a desk robot with a bendy neck from card.|Place the LED in the head and cover the inside with foil to reflect light.|Switch off the room light and watch it glow.|Test how well you can read under it.", "Reflectors direct light where you need it.", "Make it brighter with more foil.", "t"],
["Pressure-Plate Treasure Chest", "squish", 55, 3, "battery holder (2×AA),AA batteries,buzzer (3V),crocodile clip leads,aluminium foil,sponge,cardboard box,paint", "Build a treasure chest from a small box.|Make a pressure plate with two foil sheets separated by a sponge frame.|Hide it under a rug in front of the chest.|! A grown-up wires the plate, buzzer and battery.|Step on the plate and the buzzer sounds.", "A pressure plate is a pushbutton under your foot.", "Make the buzzer sound only if two plates are pressed.", "t"],
["Wobble-Warning Wall", "tilt", 55, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,cardboard box,marbles,paper cups", "! A grown-up keeps marbles away from little ones.|Build a card wall and set a tilt switch behind it.|! A grown-up wires an LED beside the switch.|Wobble the table gently: the marble rolls and the LED lights.|Adjust the tray to make it more or less sensitive.", "A tilt switch warns when something moves.", "Protect a stack of cups with it.", "t"],
["Self-stopping Buggy", "bump:m", 60, 3, "cardboard box,bottle caps,wooden skewers,drinking straws,hobby motor (3V),battery holder (2×AA),AA batteries,aluminium foil,paper clips,crocodile clip leads,lolly sticks", "Build a buggy with a long front feeler made from a lolly stick.|Line the feeler's back with foil so it closes a circuit when bent.|! A grown-up wires the motor and the feeler switch.|Drive it towards a wall: it stops when it touches.|Move the wall and let it start again.", "A feeler senses obstacles by contact.", "Make it back away from the wall.", "t"],
["Robot That Says Hello", "squish", 50, 3, "battery holder (2×AA),AA batteries,buzzer (3V),crocodile clip leads,aluminium foil,cardboard box,sponge,googly eyes", "Build a robot with a squishable hand made of foil and sponge.|Make the hand switch with two foil layers.|! A grown-up wires the hand, buzzer and battery.|Shake the robot's hand: it buzzes hello.|Decorate with eyes and a smile.", "A hand shake is a pressure switch.", "Make it greet different people with different beeps.", "t"],
["Weather Vane Reader", "windspinner", 50, 2, "paper plates,wooden skewers,sticky tack,twigs,paint,paper", "Cut an arrow from card and balance it on a skewer.|Mark N, E, S, W on a plate and place it on the ground.|Point the base north using a phone compass.|Record the arrow's direction at three times of day.|Make a chart of wind direction.", "Wind direction matters for sailing and for forecasts.", "Add a spinning cup meter to measure speed.", "o"]
]);

/* v8c.js */
/* Volume 8 (continued) — sensors & control. A grown-up checks every circuit first. */
INV.vol(8, [
["Squeeze-Sensing Pet Rock", "squish", 50, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,sponge,fabric scraps,googly eyes", "Wrap a layer of foil, a thin sponge and another layer of foil around a stone-sized lump of card.|! A grown-up wires the two foil layers and an LED through the battery pack.|Cover the outside in fabric and add googly eyes.|Squeeze: the foil touches and the eyes light.|Let go and watch the light fade.", "A squeeze sensor is a switch that closes when pressure presses two metal layers together.", "Make it light up brighter the harder you squeeze.", "t"],
["Whack-the-Switch Reaction Game", "squish", 55, 3, "battery holder (2×AA),AA batteries,buzzer (3V),LED (3V),crocodile clip leads,aluminium foil,cardboard box,sponge,timer", "Build three pressure pads from foil and sponge and mount them on a box lid.|! A grown-up wires each pad to the battery and an LED so that pressing lights it.|Ask a friend to call out a colour and press the matching pad quickly.|Time how long reactions take.|Compare your fastest time with theirs.", "Pressing a pad is an input, and the light is an output.", "Add a buzzer for a wrong answer.", "t"],
["Tilt-Controlled Night Light", "tilt", 55, 3, "battery holder (2×AA),AA batteries,LED (3V),crocodile clip leads,aluminium foil,cardboard box,marbles,paper cups", "! A grown-up keeps marbles away from little ones.|Make a card tilt tray with two foil strips and a loose marble.|Fix it to a card owl so that when it tilts, the marble joins the strips.|! A grown-up wires an LED so that tilting the owl turns its eyes on.|Rock the owl to wake its eyes and set it upright to sleep.", "Tilt switches sense a change of angle.", "Make the owl blink by tapping it.", "t"],
["Dark Detector Cupboard Alarm", "nightbot", 55, 3, "solar garden light,cardboard box,paper cups,aluminium foil,masking tape,paint", "! A grown-up opens an old solar light and keeps the batteries in their holder.|Build a small box and fit the light's sensor on its outside and the LED inside.|Cover the sensor with your hand and watch the LED come on.|Mount the box on a cupboard door so that opening it lets in light.|Test and write down what the sensor decides in each case.", "A light sensor can tell you whether a door is open or shut.", "Make an alarm for a biscuit tin.", "t"],
["Self-parking Buggy", "bump:m", 70, 3, "cardboard box,bottle caps,wooden skewers,drinking straws,hobby motor (3V),battery holder (2×AA),AA batteries,aluminium foil,paper clips,crocodile clip leads,lolly sticks,rubber bands", "Build a buggy with a bumper feeler at the front, as in Self-stopping Buggy.|! A grown-up wires the motor so that the bumper switch cuts power.|Build a card garage with a back wall.|Drive the buggy in so the bumper touches the wall and stops it.|Test several runs and adjust the bumper position.", "A bumper switch turns contact into a stop command.", "Add a buzzer that beeps when it parks.", "t"],
["Pressure Pad Doorbell", "squish", 50, 3, "battery holder (2×AA),AA batteries,buzzer (3V),crocodile clip leads,aluminium foil,sponge,cardboard box,paint", "Cut a doormat-size piece of card and make a foil-sponge-foil pad.|! A grown-up wires the pad, buzzer and battery.|Hide the buzzer behind a card door.|Stand on the mat and the buzzer sounds.|Decorate the mat with 'Welcome' lettering.", "A pressure pad is a switch you press with your foot.", "Make it play different tones for different mats.", "t"],
["Shake-to-Wake Robot", "tilt", 55, 3, "battery holder (2×AA),AA batteries,LED (3V),buzzer (3V),crocodile clip leads,aluminium foil,marbles,paper cups,googly eyes", "! A grown-up keeps marbles away from little ones.|Build a robot head with a hidden shake switch from a foil tray and marble.|! A grown-up wires the LED eyes and the buzzer to the switch.|Shake the robot gently and it wakes up with lights and a beep.|Keep it still and it goes quiet.", "A shake sensor wakes a device when it moves.", "Make the eyes stay lit for a few seconds.", "t"],
["If-Then Robot Cards", "master", 40, 2, "paper,thin card,pom-poms,googly eyes", "Draw four robot situations on cards, like 'it is dark' or 'something is in the way'.|Write an 'IF this THEN do that' rule on each card.|Act out being the robot and follow the rules with a friend.|Swap in a new rule and see what happens.|Draw a flow chart with arrows for your best robot.", "Robots follow rules of the form 'if this, then that'.", "Write rules for a robot that waters plants.", "t"],
["Sensor Spotting Walk", "squish", 35, 1, "paper,pencil,thin card", "Walk round your home with a grown-up and spot ten machines that sense something, like an automatic light or a lift.|Draw each one in a table and write what it senses.|Write what it does in response.|Rank them from smartest to simplest.|Share your list with someone.", "Sensors are everywhere, from doors to doorbells.", "Invent a new machine with a sensor you have never seen.", "t"]
]);

